import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';


export type RedBouncingBallProps = Record<string, any>;

const RedBouncingBall: React.FC<RedBouncingBallProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  ballColor = "#ff0000",
  ballSize = 150,
  bounceHeight = 0.5,
  bouncesPerSecond = 1,
  moveHorizontally = true,
  groundPosition = 0.8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Parse background color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Time and progress calculations
  const timeInSeconds = frame / fps;
  // Offset by 0.5 so the ball drops from the peak at t=0
  const progress = ((timeInSeconds * bouncesPerSecond) + 0.5) % 1;

  const maxBounceHeight = height * bounceHeight;

  // Split into up/down segments to apply distinct physics curves
  const isUp = progress <= 0.5;
  const upProgress = isUp ? progress / 0.5 : 0;
  const downProgress = !isUp ? (progress - 0.5) / 0.5 : 0;

  const yUp = interpolate(upProgress, [0, 1], [0, -maxBounceHeight], {
    easing: Easing.out(Easing.quad), // Slows down as it reaches the peak
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const yDown = interpolate(downProgress, [0, 1], [-maxBounceHeight, 0], {
    easing: Easing.in(Easing.quad), // Accelerates as it falls
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const translateY = isUp ? yUp : yDown;

  // Squash and stretch mapping
  // 0 & 1 = hitting the ground (squashed)
  // 0.5 = peak (perfectly round)
  // 0.1 & 0.9 = flying fast (stretched)
  const currentScaleX = interpolate(
    progress,
    [0, 0.1, 0.5, 0.9, 1],
    [1.3, 0.9, 1, 0.9, 1.3],
    { easing: Easing.ease, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const currentScaleY = interpolate(
    progress,
    [0, 0.1, 0.5, 0.9, 1],
    [0.7, 1.1, 1, 1.1, 0.7],
    { easing: Easing.ease, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Shadow responds to height (translateY is negative, so map from -maxBounceHeight to 0)
  const shadowScale = interpolate(translateY, [-maxBounceHeight, 0], [0.2, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const shadowOpacity = interpolate(translateY, [-maxBounceHeight, 0], [0.05, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Optional horizontal movement mapping
  const startX = moveHorizontally ? -ballSize * 2 : width / 2;
  const endX = moveHorizontally ? width + ballSize * 2 : width / 2;
  const translateX = interpolate(frame, [0, durationInFrames], [startX, endX]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: translateX,
          top: height * groundPosition,
          width: 0,
          height: 0,
          transition: "none",
        }}
      >
        {/* Dynamic Shadow */}
        <div
          style={{
            position: "absolute",
            left: -ballSize / 2,
            top: -ballSize * 0.1,
            width: ballSize,
            height: ballSize * 0.2,
            backgroundColor: "black",
            borderRadius: "50%",
            opacity: shadowOpacity,
            transform: `scale(${shadowScale})`,
            filter: `blur(${ballSize * 0.06}px)`,
            transition: "none",
          }}
        />

        {/* Animated Ball */}
        <div
          style={{
            position: "absolute",
            left: -ballSize / 2,
            bottom: 0,
            width: ballSize,
            height: ballSize,
            backgroundColor: ballColor,
            borderRadius: "50%",
            transformOrigin: "bottom center", // Ensure squash/stretch locks to the ground
            transform: `translateY(${translateY}px) scaleX(${currentScaleX}) scaleY(${currentScaleY})`,
            transition: "none",
          }}
        >
          {/* Faux 3D Inner Highlight / Shadow */}
          <div
            style={{
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              background:
                "radial-gradient(circle at 35% 25%, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0) 40%, rgba(0,0,0,0) 60%, rgba(0,0,0,0.6) 100%)",
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default RedBouncingBall;